#undef RUSTORB_SYSTEM_EXCEPTION

inline std::ostream& operator<<(std::ostream& os, const Exception& e) {
  os << "CORBA::" << e._name();
  if (auto* s = dynamic_cast<const SystemException*>(&e)) {
    static const char* const completed[] = {"COMPLETED_YES", "COMPLETED_NO", "COMPLETED_MAYBE"};
    os << " (minor 0x" << std::hex << s->minor() << std::dec << ", "
       << completed[static_cast<uint32_t>(s->completed()) % 3] << ")";
  }
  return os;
}

template <typename T> void object_reference<T>::throw_nil() {
  throw INV_OBJREF(0, CompletionStatus::COMPLETED_NO);
}

