#define RUSTORB_POLICY(NAME, ID, VALUE)                                         \
  class NAME : public detail::PolicyOf<ID, VALUE> {                              \
   public:                                                                       \
    explicit NAME(VALUE v) : PolicyOf(v) {}                                      \
    CORBA::object_reference<CORBA::Policy> copy() override {                     \
      return CORBA::object_reference<CORBA::Policy>(std::make_shared<NAME>(value())); \
    }                                                                            \
  };

